<?php
declare(strict_types=1);
namespace TempNumber;
putenv('DB_DSN=sqlite::memory:');putenv('APP_ENV=testing');
require __DIR__.'/../src/bootstrap.php';foreach(['Wallet','Pricing','Providers','Rentals','Commerce','Reconciliation','NumberSync']as$file)require_once __DIR__.'/../src/'.$file.'.php';require_once __DIR__.'/../src/FiveSimProvider.php';
foreach(glob(__DIR__.'/../migrations/*.sql')as$file)db()->exec(file_get_contents($file));
$fixture=Pricing::setting('5sim_pricing');$fixture['retail_margin_cents']=70;$fixture['wholesale_margin_cents']=$fixture['retail_margin_cents'];query("UPDATE settings SET value=? WHERE name='5sim_pricing'",[json_encode($fixture)]);
$passed=0;
function eq(mixed$a,mixed$b):void{if($a!==$b)throw new \RuntimeException(var_export($a,true).' !== '.var_export($b,true));}
function rejects(callable$fn,string$code):void{try{$fn();}catch(Problem$e){eq($e->key,$code);return;}throw new \RuntimeException('Expected '.$code);}
function test(string$name,callable$fn):void{global$passed;foreach(['reward_costs','messages','provider_receipts','fivesim_requests','fivesim_cache','orders','ledger','wallets','users']as$table)query('DELETE FROM '.$table);$_GET=[];$fn();$passed++;echo "PASS $name\n";}
function customer(int$funds=10000):array{$id=id();query('INSERT INTO users (id,name,email,password_hash,referral_code,created_at) VALUES (?,?,?,?,?,?)',[$id,'Global QA',$id.'@example.invalid','unused',id(),now()]);query('INSERT INTO wallets (user_id,balance_cents) VALUES (?,?)',[$id,$funds]);return ['id'=>$id];}
function fake(?callable$override=null):array{
 $state=(object)['buys'=>0,'cancels'=>0,'finishes'=>0,'reads'=>0,'status'=>'PENDING','sms'=>null,'offers'=>['england'=>['cheap'=>['cost'=>0.1,'count'=>10,'rate'=>70],'high'=>['cost'=>0.4,'count'=>10,'rate'=>98],'empty'=>['cost'=>0.2,'count'=>0,'rate'=>100],'unknown'=>['cost'=>0.01,'count'=>99]],'germany'=>['best'=>['cost'=>0.9,'count'=>10,'rate'=>99]]]];
 $p=new FiveSimProvider(function($path,$auth)use($state,$override){$urlPath=parse_url($path,PHP_URL_PATH);parse_str(parse_url($path,PHP_URL_QUERY)??'',$query);$state->reads++;if($override){$result=$override($urlPath,$query,$state);if($result!==null)return$result;}
  $detail=fn()=>['id'=>501,'phone'=>'+447350690992','operator'=>'high','product'=>'facebook','price'=>0.4,'status'=>$state->status,'expires'=>'2099-01-01T12:00:00Z','sms'=>$state->sms,'country'=>'england'];
  if($urlPath==='/guest/products/any/any')$data=['facebook'=>['Category'=>'activation'],'hosting'=>['Category'=>'hosting']];
  elseif($urlPath==='/guest/countries')$data=['england'=>['text_en'=>'England','iso'=>['gb'=>1]],'germany'=>['text_en'=>'Germany','iso'=>['de'=>1]]];
  elseif($urlPath==='/guest/prices')$data=isset($query['country'])?[$query['country']=>['facebook'=>$state->offers[$query['country']]??[]]]:['facebook'=>$state->offers];
  elseif(str_starts_with($urlPath,'/user/buy/activation/')){eq($auth,true);eq($urlPath,'/user/buy/activation/england/high/facebook');$state->buys++;$data=$detail();}
  elseif($urlPath==='/user/check/501')$data=$detail();
  elseif($urlPath==='/user/cancel/501'){$state->cancels++;$state->status='CANCELED';$data=$detail();}
  elseif($urlPath==='/user/finish/501'){$state->finishes++;$state->status='FINISHED';$data=$detail();}
  else throw new \RuntimeException('Unexpected '.$path);
  return ['http'=>200,'data'=>$data,'raw'=>json_encode($data)];
 });return[$p,$state];
}
function input(FiveSimProvider$p):array{$prices=$p->prices('facebook',Pricing::setting('5sim_pricing'));foreach($prices['items']as$row)if($row['country']==='england')return ['catalogue'=>'global','country'=>'england','service'=>'facebook','max_price_usd'=>$row['price_usd'],'options'=>['quote_id'=>$row['quote_id']]];throw new \RuntimeException('No offer');}
function buy(array$u,FiveSimProvider$p,?string$key=null):array{return Rentals::purchase($u,input($p),$key??id(),false,$p);}

test('Highest delivery rate wins even when the lower-rate option is cheaper',function(){[$p]=fake();$data=$p->prices('facebook',Pricing::setting('5sim_pricing'));eq(count($data['items']),2);eq($data['items'][0]['operator'],'high');eq($data['items'][0]['price_usd'],'1.10');eq($data['best_country'],'germany');eq(str_contains(json_encode($data),'cost_minor'),false);});
test('Unknown zero invalid and out-of-stock rates cannot be selected',function(){eq(FiveSimProvider::best(['a'=>['cost'=>1,'count'=>0,'rate'=>100],'b'=>['cost'=>1,'count'=>1],'c'=>['cost'=>1,'count'=>1,'rate'=>101],'d'=>['cost'=>1,'count'=>1,'rate'=>0]]),null);});
test('Equal success rates choose the lower priced operator deterministically',function(){eq(FiveSimProvider::best(['z'=>['cost'=>1,'count'=>1,'rate'=>99],'b'=>['cost'=>0.4,'count'=>2,'rate'=>99],'a'=>['cost'=>0.4,'count'=>2,'rate'=>99]])['operator'],'a');});
test('Fractional USD supplier prices round up to exact USD pennies before the approved margin',function(){eq(FiveSimProvider::cents('0.0897'),9);eq(Pricing::numberQuote(9,'5sim',Pricing::setting('5sim_pricing')),79);rejects(fn()=>FiveSimProvider::cents(-1),'INVALID_PROVIDER_PRICE');});
test('Purchase issues exactly the quoted highest-rate operator and charges once on retry',function(){[$p,$s]=fake();$u=customer();$input=input($p);$key=id();$a=Rentals::purchase($u,$input,$key,false,$p);$b=Rentals::purchase($u,$input,$key,false,$p);eq($a['status'],'active');eq($a['id'],$b['id']);eq($a['operator'],'high');eq($a['country_code'],'GB');eq($a['can_cancel'],true);eq($s->buys,1);eq(Wallet::balance($u['id'])['balance_usd'],'98.90');});
test('A changed best operator is rejected before reservation or dispatch',function(){[$p,$s]=fake();$input=input($p);$s->offers['england']['cheap']['rate']=100;$u=customer();rejects(fn()=>Rentals::purchase($u,$input,id(),false,$p),'QUOTE_CHANGED');eq(Wallet::balance($u['id'])['balance_usd'],'100.00');eq($s->buys,0);});
test('A supplier price increase requires a refreshed quote',function(){[$p,$s]=fake();$input=input($p);$s->offers['england']['high']['cost']=0.5;rejects(fn()=>Rentals::purchase(customer(),$input,id(),false,$p),'QUOTE_CHANGED');eq($s->buys,0);});
test('Stale and forged quotes and mismatched countries cannot spend wallet funds',function(){[$p]=fake();$input=input($p);$u=customer();$forged=$input;$forged['options']['quote_id']=str_repeat('a',32);rejects(fn()=>Rentals::purchase($u,$forged,id(),false,$p),'QUOTE_EXPIRED');$wrong=$input;$wrong['country']='germany';rejects(fn()=>Rentals::purchase($u,$wrong,id(),false,$p),'QUOTE_MISMATCH');query("UPDATE fivesim_cache SET expires_at='2000-01-01 00:00:00' WHERE id=?",['quote:'.$input['options']['quote_id']]);rejects(fn()=>Rentals::purchase($u,$input,id(),false,$p),'QUOTE_EXPIRED');});
test('Insufficient balance and accepted USD price caps prevent a provider purchase',function(){[$p,$s]=fake();rejects(fn()=>buy(customer(109),$p),'INSUFFICIENT_FUNDS');$input=input($p);$input['max_price_usd']='1.09';rejects(fn()=>Rentals::purchase(customer(),$input,id(),false,$p),'PRICE_EXCEEDS_MAX');eq($s->buys,0);});
test('Definitive no-free-phones response releases the reservation once',function(){[$p]=fake(fn($path)=>str_starts_with($path,'/user/buy/')?['http'=>200,'raw'=>'no free phones','data'=>null]:null);$u=customer();$input=input($p);$key=id();eq(Rentals::purchase($u,$input,$key,false,$p)['status'],'cancelled');Rentals::purchase($u,$input,$key,false,$p);eq(Wallet::balance($u['id'])['balance_usd'],'100.00');eq(Wallet::balance($u['id'])['reserved_usd'],'0.00');});
test('Ambiguous purchases are never replayed and a replacement is blocked while pending',function(){[$p,$s]=fake(function($path,$query,$state){if(str_starts_with($path,'/user/buy/')){$state->buys++;throw new AmbiguousProvisioning('Connection lost');}return null;});$u=customer();$input=input($p);$key=id();$a=Rentals::purchase($u,$input,$key,false,$p);eq($a['status'],'reconciliation');Rentals::purchase($u,$input,$key,false,$p);rejects(fn()=>$p->findIntent($a['id']),'RECONCILIATION_REQUIRED');rejects(fn()=>Rentals::purchase($u,input($p),id(),false,$p),'ORDER_PENDING');eq($s->buys,1);eq(Wallet::balance($u['id'])['reserved_usd'],'1.10');});
test('Supplier purchase mismatches remain reserved and never silently substitute operators',function(){[$p]=fake(fn($path)=>str_starts_with($path,'/user/buy/')?['http'=>200,'raw'=>'','data'=>['id'=>501,'operator'=>'cheap','product'=>'facebook','phone'=>'+447350690992','country'=>'england','expires'=>'2099-01-01T12:00:00Z','price'=>0.1,'status'=>'PENDING']]:null);$u=customer();eq(buy($u,$p)['status'],'reconciliation');eq(Wallet::balance($u['id'])['reserved_usd'],'1.10');});
test('Leading-zero SMS codes and plain text are preserved',function(){[$p,$s]=fake();$u=customer();$o=buy($u,$p);$s->status='RECEIVED';$s->sms=[['code'=>'001234','text'=>'Your code is 001234','date'=>'2026-10-21T10:00:00Z']];$r=Rentals::sync(Rentals::owned($o['id'],$u['id']),false,$p);eq($r['sms_code'],'001234');eq($r['status'],'completed');eq($r['messages'][0]['body'],'Your code is 001234');});
test('A received label alone never invents a code or completed order',function(){[$p,$s]=fake();$u=customer();$o=buy($u,$p);$s->status='RECEIVED';eq(Rentals::sync(Rentals::owned($o['id'],$u['id']),false,$p)['status'],'active');});
test('Customer cancellation reaches 5sim and refunds the original charge once',function(){[$p,$s]=fake();$u=customer();$o=buy($u,$p);$r=Rentals::sync(Rentals::owned($o['id'],$u['id']),true,$p);eq($r['status'],'cancelled');eq($s->cancels,1);Rentals::sync(Rentals::owned($o['id'],$u['id']),true,$p);eq($s->cancels,1);eq(Wallet::balance($u['id'])['balance_usd'],'100.00');});
foreach(['CANCELED','TIMEOUT']as$status)test('Provider '.$status.' is imported by background sync with one refund',function()use($status){[$p,$s]=fake();$u=customer();$o=buy($u,$p);$s->status=$status;query("UPDATE orders SET updated_at='2000-01-01 00:00:00' WHERE id=?",[$o['id']]);eq(NumberSync::run($u['id'],$p)['synced'],1);eq(Wallet::balance($u['id'])['balance_usd'],'100.00');eq($s->cancels,0);});
test('Provider outage does not imply cancellation or refund',function(){ $down=false;[$p]=fake(function($path)use(&$down){if($down&&$path==='/user/check/501')return ['http'=>503,'data'=>null,'raw'=>'offline'];return null;});$u=customer();$o=buy($u,$p);$down=true;rejects(fn()=>Rentals::sync(Rentals::owned($o['id'],$u['id']),false,$p),'PROVIDER_UNAVAILABLE');eq(Wallet::balance($u['id'])['balance_usd'],'98.90');eq(Rentals::owned($o['id'],$u['id'])['status'],'active');});
test('Delivered codes win over cancellation labels and block refunds',function(){[$p,$s]=fake();$u=customer();$o=buy($u,$p);$s->status='CANCELED';$s->sms=[['code'=>'0123','text'=>'Code 0123']];$r=Rentals::sync(Rentals::owned($o['id'],$u['id']),false,$p);eq($r['status'],'completed');eq(Wallet::balance($u['id'])['balance_usd'],'98.90');});
test('Foreign owners and mismatched provider SMS identity are rejected',function(){[$p]=fake();$u=customer();$o=buy($u,$p);rejects(fn()=>Rentals::owned($o['id'],customer()['id']),'NOT_FOUND');[$bad]=fake(fn($path)=>$path==='/user/check/501'?['http'=>200,'raw'=>'','data'=>['id'=>501,'phone'=>'+19999999999','product'=>'facebook','country'=>'england','operator'=>'high','status'=>'RECEIVED','sms'=>[['code'=>'123','text'=>'Other account']]]]:null);rejects(fn()=>Rentals::sync(Rentals::owned($o['id'],$u['id']),false,$bad),'INVALID_PROVIDER_RESPONSE');});
test('Saved provider responses recover local activation without a second purchase',function(){[$p,$s]=fake();$u=customer();$o=buy($u,$p);$receipt=$p->findIntent($o['id']);eq($receipt['outcome'],'provisioned');eq($s->buys,1);eq($receipt['receipt']['id'],'501');});
test('RECEIVED means waiting for SMS and remains cancellable with a full refund',function(){[$p,$s]=fake();$u=customer();$s->status='RECEIVED';$o=buy($u,$p);eq($o['can_cancel'],true);eq(Rentals::sync(Rentals::owned($o['id'],$u['id']),false,$p)['can_cancel'],true);$r=Rentals::sync(Rentals::owned($o['id'],$u['id']),true,$p);eq($r['status'],'cancelled');eq($s->cancels,1);eq($r['refund_usd'],'1.10');eq(Wallet::balance($u['id'])['balance_usd'],'100.00');Rentals::sync(Rentals::owned($o['id'],$u['id']),true,$p);eq((int)one("SELECT COUNT(*) AS n FROM ledger WHERE kind='refund'")['n'],1);});
test('Cancellation response lost after provider cancellation is recovered and refunded once',function(){[$p,$s]=fake(function($path,$query,$s){if($path==='/user/cancel/501'){$s->cancels++;$s->status='CANCELED';return ['http'=>503,'raw'=>'offline','data'=>null];}return null;});$u=customer();$o=buy($u,$p);$r=Rentals::sync(Rentals::owned($o['id'],$u['id']),true,$p);eq($r['status'],'cancelled');eq(Wallet::balance($u['id'])['balance_usd'],'100.00');eq($s->cancels,1);});
test('An unconfirmed cancellation is reported instead of silently succeeding or refunding',function(){[$p,$s]=fake(fn($path)=>$path==='/user/cancel/501'?['http'=>200,'raw'=>'','data'=>['id'=>501,'phone'=>'+447350690992','country'=>'england','product'=>'facebook','status'=>'RECEIVED','sms'=>null]]:null);$u=customer();$o=buy($u,$p);rejects(fn()=>Rentals::sync(Rentals::owned($o['id'],$u['id']),true,$p),'CANCELLATION_UNCONFIRMED');eq(Rentals::owned($o['id'],$u['id'])['status'],'active');eq(Wallet::balance($u['id'])['balance_usd'],'98.90');});
test('Developer API can purchase Global numbers with source attribution and retry safety',function(){[$p,$state]=fake();$u=customer();$body=input($p);$key=id();$order=Rentals::purchase($u,$body,$key,true,$p);eq($order['product'],'global');eq($state->buys,1);eq(Rentals::owned($order['id'],$u['id'])['price_tier'],'wholesale');$again=Rentals::purchase($u,$body,$key,true,$p);eq($again['id'],$order['id']);eq($state->buys,1);});
test('Finish sends the owned Global order to the provider and preserves delivered code',function(){[$p,$state]=fake();$u=customer();$order=buy($u,$p);$state->sms=[['code'=>'000123','text'=>'Your code is 000123']];$result=Rentals::settle($order['id'],$p->finish($order['provider_order_id']));eq($state->finishes,1);eq($result['status'],'completed');eq($result['sms_code'],'000123');eq($result['refund_usd'],null);});
echo "$passed 5sim tests passed\n";
